    ////////////////////////////////////////////////////////

    ////////////////////////////////////////////////////////
    //
    // Folding main seed loops into destination
    //
    TwistSquash::SquashB(pWorkSpace->mCrystalLaneA, pWorkSpace->mCrystalLaneB, pWorkSpace->mCrystalLaneC, pWorkSpace->mCrystalLaneD, pDestination);
    //
    ////////////////////////////////////////////////////////

    *pIngress = aIngress;
    *pCarry = aCarry;
    *pWandererA = aWandererA;
    *pWandererB = aWandererB;
    *pWandererC = aWandererC;
    *pWandererD = aWandererD;
    *pWandererE = aWandererE;
    *pWandererF = aWandererF;
    *pWandererG = aWandererG;
    *pWandererH = aWandererH;
    *pWandererI = aWandererI;
    *pWandererJ = aWandererJ;
    *pWandererK = aWandererK;

    ////////////////////////////////////////////////////////
    //
    // Independent key-row flows
    //
    // Key flow — A / A

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Capella_Arx::KEY_A_A_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Capella_Arx::KEY_A_A_B(PARAMS_SEED);

    KeyDiffuse_A_A_A(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Capella_Arx::KEY_A_A_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Capella_Arx::KEY_A_A_D(PARAMS_SEED);

    KeyDiffuse_B_A_A(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Capella_Arx::KEY_A_A_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CAPELLA_KEY_A_A_IceLaneA, CAPELLA_KEY_A_A_IceLaneB, CAPELLA_KEY_A_A_IceLaneC, CAPELLA_KEY_A_A_IceLaneD, &(pWorkSpace->mKeyBoxA[0U][0]));

    // Key flow — A / B

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Capella_Arx::KEY_A_B_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Capella_Arx::KEY_A_B_B(PARAMS_SEED);

    KeyDiffuse_A_A_B(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Capella_Arx::KEY_A_B_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Capella_Arx::KEY_A_B_D(PARAMS_SEED);

    KeyDiffuse_B_A_B(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Capella_Arx::KEY_A_B_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CAPELLA_KEY_A_B_IceLaneA, CAPELLA_KEY_A_B_IceLaneB, CAPELLA_KEY_A_B_IceLaneC, CAPELLA_KEY_A_B_IceLaneD, &(pWorkSpace->mKeyBoxA[1U][0]));

    // Key flow — A / C

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Capella_Arx::KEY_A_C_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Capella_Arx::KEY_A_C_B(PARAMS_SEED);

    KeyDiffuse_A_A_C(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Capella_Arx::KEY_A_C_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Capella_Arx::KEY_A_C_D(PARAMS_SEED);

    KeyDiffuse_B_A_C(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Capella_Arx::KEY_A_C_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CAPELLA_KEY_A_C_IceLaneA, CAPELLA_KEY_A_C_IceLaneB, CAPELLA_KEY_A_C_IceLaneC, CAPELLA_KEY_A_C_IceLaneD, &(pWorkSpace->mKeyBoxA[2U][0]));

    // Key flow — A / D

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Capella_Arx::KEY_A_D_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
